import { Component, OnDestroy } from '@angular/core';
import { NgFor, NgIf } from '@angular/common';
import { Subscription, timer } from 'rxjs';
import { ToastMessage, ToastService } from '../services/toast.service';

@Component({
  selector: 'app-toast',
  standalone: true,
  imports: [NgFor, NgIf],
  template: `
    <div class="toast-container" aria-live="polite" aria-atomic="true">
      <div class="toast" *ngFor="let t of toasts" [class.toast-error]="t.type==='error'"
           [class.toast-success]="t.type==='success'" [class.toast-warning]="t.type==='warning'"
           [class.toast-info]="t.type==='info'">
        <div class="toast-header" *ngIf="t.title">{{t.title}}</div>
        <div class="toast-body">{{t.message}}</div>
        <button class="toast-close" (click)="dismiss(t.id!)">×</button>
      </div>
    </div>
  `,
  styles: [
    `.toast-container { position: fixed; top: 1rem; right: 1rem; z-index: 2000; display: flex; flex-direction: column; gap: .5rem; }`,
    `.toast { position: relative; min-width: 240px; max-width: 420px; padding: .75rem 2rem .75rem .75rem; border-radius: .5rem; box-shadow: 0 4px 12px rgba(0,0,0,.12); color: #222; background: #fff; border: 1px solid #e5e5e5; }`,
    `.toast-header { font-weight: 600; margin-bottom: .25rem; }`,
    `.toast-body { font-size: .9rem; line-height: 1.25rem; }`,
    `.toast-close { position: absolute; top: .25rem; right: .5rem; background: transparent; border: none; font-size: 1.25rem; cursor: pointer; color: #666; }`,
    `.toast-error { border-left: 4px solid #e74c3c; }`,
    `.toast-success { border-left: 4px solid #27ae60; }`,
    `.toast-warning { border-left: 4px solid #f39c12; }`,
    `.toast-info { border-left: 4px solid #3498db; }`,
  ]
})
export class ToastComponent implements OnDestroy {
  toasts: ToastMessage[] = [];
  private sub: Subscription;

  constructor(private toast: ToastService) {
    this.sub = this.toast.messages$.subscribe(msg => {
      this.toasts = [...this.toasts, msg];
      const timeout = msg.timeoutMs ?? 5000;
      timer(timeout).subscribe(() => this.dismiss(msg.id!));
    });
  }

  dismiss(id: number) {
    this.toasts = this.toasts.filter(t => t.id !== id);
  }

  ngOnDestroy() {
    this.sub.unsubscribe();
  }
}
